//! Parity with Python's `csv` module, spelled out one shape at a time.
//!
//! The corpus (`tests/fixtures/`) is generated by Python's own `csv` module
//! and compared byte for byte by `tests/test_csv_crosslib.py` at the
//! repository root - that is the live oracle. This file is the same
//! agreement written out by hand, so a reader can see *which* rule of
//! Python's writer the engine matches and which rule it deliberately does
//! not, without having to run Python at all.
//!
//! Python's `csv.writer` in its default (`QUOTE_MINIMAL`) mode quotes a
//! field when it holds the delimiter, the quote character, or a character of
//! the record terminator it was given - and for nothing else. The engine
//! matches that, and adds one rule of its own that Python does not have:
//!
//! - A field with leading or trailing whitespace is quoted. Python treats
//!   whitespace as content and writes it raw; the YAML side would trim it,
//!   so the quotes are what keep the text intact across the hub.
//!
//! That difference is why the corpus holds no such field: the two
//! implementations agree on every byte of it.
//!
//! A field holding a bare `CR` is *not* a difference, and used to be written
//! down as one. Measured on CPython 3.12, `csv.writer` quotes a field that
//! holds a `CR` whatever record terminator it was given - the `'\r\n'` in the
//! documentation is the set of characters that trigger the quoting, not the
//! terminator that was configured - so the engine's quoting of a bare `CR` is
//! Python's rule and RFC 4180's rule at once.

use pyrs_csv::{
    CsvOptions, Delimiter, LineTerminator, from_csv_with_options, to_csv_text_with_options,
};

/// The engine's rendering of a document.
fn engine_writes(text: &str, options: &CsvOptions) -> String {
    let node = from_csv_with_options(text, options).expect("the document parses");
    to_csv_text_with_options(&node, options).expect("the document writes back")
}

/// The options Python's `csv.writer` is in when it writes CRLF records.
fn crlf() -> CsvOptions {
    CsvOptions {
        line_terminator: LineTerminator::CrLf,
        ..CsvOptions::default()
    }
}

#[test]
fn a_plain_table_is_written_the_way_python_writes_it() {
    // python -c 'import csv,io; b=io.StringIO(); csv.writer(b).writerows([["id","name"],["1","web-1"]]); print(repr(b.getvalue()))'
    // -> 'id,name\r\n1,web-1\r\n'
    assert_eq!(
        engine_writes("id,name\n1,web-1\n", &crlf()),
        "id,name\r\n1,web-1\r\n"
    );
}

#[test]
fn a_field_holding_the_delimiter_is_quoted_the_way_python_quotes_it() {
    // csv.writer(...).writerows([["a"],["x,y"]]) -> 'a\r\n"x,y"\r\n'
    assert_eq!(engine_writes("a\n\"x,y\"\n", &crlf()), "a\r\n\"x,y\"\r\n");
}

#[test]
fn a_field_holding_a_quote_is_quoted_the_way_python_quotes_it() {
    // csv.writer(...).writerows([["a"],['say "hi"']]) -> 'a\r\n"say ""hi"""\r\n'
    assert_eq!(
        engine_writes("a\nsay \"hi\"\n", &crlf()),
        "a\r\n\"say \"\"hi\"\"\"\r\n"
    );
}

#[test]
fn a_field_holding_a_line_break_is_quoted_the_way_python_quotes_it() {
    // csv.writer(...).writerows([["a"],["line1\nline2"]]) -> 'a\r\n"line1\nline2"\r\n'
    assert_eq!(
        engine_writes("a\n\"line1\nline2\"\n", &crlf()),
        "a\r\n\"line1\nline2\"\r\n"
    );
}

#[test]
fn a_tab_delimited_document_matches_pythons_tab_writer() {
    let options = CsvOptions {
        delimiter: Delimiter::Tab,
        ..crlf()
    };
    assert_eq!(
        engine_writes("id\tname\n1\tweb-1\n", &options),
        "id\tname\r\n1\tweb-1\r\n"
    );
}

#[test]
fn a_leading_zero_is_not_re_serialized_the_way_python_keeps_it() {
    // Python has no types, so `007` is text there too - and the engine keeps
    // the same spelling rather than resolving the cell to an integer and
    // writing the integer back.
    assert_eq!(
        engine_writes("code\n007\n", &CsvOptions::default()),
        "code\n007\n"
    );
}

#[test]
fn a_null_cell_keeps_its_spelling() {
    assert_eq!(
        engine_writes("a\nnull\n", &CsvOptions::default()),
        "a\nnull\n"
    );
}

#[test]
fn an_empty_cell_is_an_empty_field() {
    assert_eq!(
        engine_writes("a,b\n,x\n", &CsvOptions::default()),
        "a,b\n,x\n"
    );
}

#[test]
fn a_field_holding_a_bare_carriage_return_is_quoted_the_way_python_quotes_it() {
    // Python's writer quotes a field holding a `CR` whatever terminator it
    // was given, and so does RFC 4180 and so does the engine - the three
    // rules agree here, which is why this row is a shared one.
    assert_eq!(
        engine_writes("a\nx\ry\n", &CsvOptions::default()),
        "a\n\"x\ry\"\n"
    );
}

#[test]
fn a_field_with_edge_whitespace_is_quoted_where_python_writes_it_raw() {
    // The other documented difference: Python treats whitespace as content
    // and writes it raw, while the YAML side would trim it - so the engine
    // quotes it and the text survives the hub.
    assert_eq!(
        engine_writes("a\n x \n", &CsvOptions::default()),
        "a\n\" x \"\n"
    );
}

#[test]
fn a_document_the_engine_refuses_names_its_code() {
    let error = from_csv_with_options("a,b\n1\n", &CsvOptions::default())
        .expect_err("a ragged row is refused");
    assert_eq!(error.code(), "E-CSV-002");
}
